def normalize(path):
    """Return the shortest equivalent slash-separated path."""
    absolute = path.startswith("/")
    segments = []
    for segment in path.split("/"):
        if segment in ("", "."):
            continue
        if segment == "..":
            if segments and segments[-1] != "..":
                segments.pop()
            elif not absolute:
                segments.append(segment)
        else:
            segments.append(segment)

    result = "/".join(segments)
    if absolute:
        return "/" + result
    return result or "."


def join(base, *parts):
    """Apply parts from left to right and normalize the resulting path."""
    chunks = [base] if base else []
    for part in parts:
        if part.startswith("/"):
            chunks = [part]
        elif part:
            chunks.append(part)
    return normalize("/".join(chunks))
